from pathlib import Path

ROOT = Path('/app') if Path('/app/scenario.json').exists() else Path(__file__).resolve().parents[1]
CONFIG_PATH = Path('/app/scenario.json') if Path('/app/scenario.json').exists() else ROOT / 'data/input.json'
CONFIG = json.loads(CONFIG_PATH.read_text())
INPUT = json.loads((ROOT / 'data/workload.json').read_text())
PARSER = argparse.ArgumentParser()
PARSER.add_argument('--stage', required=True, choices=CONFIG['stages'])
PARSER.add_argument('--output', default=str(ROOT / 'outputs'))
ARGS = PARSER.parse_args()
OUT = Path(ARGS.output)
OUT.mkdir(parents=True, exist_ok=True)
STAGE = ARGS.stage


def read_stage(name):
    record = json.loads((OUT / f'stage-{name}.json').read_text())
    if record['status'] != 'success' or record['stage'] != name:
        raise ValueError(f'invalid upstream stage: {name}')
    return record['result']


def previous():
    parents = CONFIG['dependencies'][STAGE]
    if len(parents) != 1:
        raise ValueError(f'{STAGE} requires an explicit parent selection')
    return read_stage(parents[0])


def write_json(name, value):
    (OUT / name).write_text(json.dumps(value, indent=2, allow_nan=False) + '\n')
    return value


def write_pickle(name, value):
    (OUT / name).write_bytes(pickle.dumps(value, protocol=4))


def write_csv(name, rows):
    with (OUT / name).open('w', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def report(name, title, value):
    (OUT / name).write_text('<!doctype html><meta charset="utf-8"><title>' + html.escape(title) + '</title><h1>' + html.escape(title) + '</h1><pre>' + html.escape(json.dumps(value, indent=2)) + '</pre>\n')


def regression(rows):
    xs = [row[0] for row in rows]
    ys = [row[1] for row in rows]
    mean_x, mean_y = statistics.mean(xs), statistics.mean(ys)
    denominator = sum((x - mean_x) ** 2 for x in xs)
    if denominator <= 0:
        raise ValueError('training inputs have zero variance')
    weight = sum((x - mean_x) * (y - mean_y) for x, y in rows) / denominator
    return {'weight': weight, 'bias': mean_y - weight * mean_x}


def predict(model, x):
    return model['weight'] * x + model['bias']


def rmse(model, rows):
    return math.sqrt(statistics.mean((predict(model, x) - y) ** 2 for x, y in rows))


def require(condition, message):
    if not condition:
        raise ValueError(message)


def run_stage():
    started = time.time_ns()
    parents = CONFIG['dependencies'][STAGE]
    for parent in parents:
        read_stage(parent)
    result = compute()
    require(isinstance(result, dict) and result, 'activity produced no domain result')
    record = {
        'showcase': CONFIG['slug'], 'stage': STAGE, 'status': 'success',
        'validationMode': 'local-workload', 'startedAtUnixNs': started,
        'finishedAtUnixNs': time.time_ns(),
        'inputDigest': hashlib.sha256(json.dumps(INPUT, sort_keys=True).encode()).hexdigest(),
        'dependencies': parents, 'result': result,
    }
    write_json(f'stage-{STAGE}.json', record)
    print(json.dumps({'activity': STAGE, 'status': 'success', 'resultKeys': list(result)}))

def tokenize(text):
    return re.findall(r'[a-z0-9]+', text.lower())


def vectorize(text, vocabulary, idf):
    tokens=tokenize(text)
    vector=[tokens.count(term)*idf[index] for index,term in enumerate(vocabulary)]
    norm=math.sqrt(sum(value*value for value in vector)) or 1
    return [value/norm for value in vector]


def retrieve(index, question):
    query=vectorize(question,index['vocabulary'],index['idf'])
    scored=[(sum(a*b for a,b in zip(query,chunk['vector'])),chunk) for chunk in index['chunks']]
    score,chunk=max(scored,key=lambda item:item[0])
    return {'score':score,'document':chunk['document'],'text':chunk['text']}


def rag_indexing():
    if STAGE == 'collect-documents':
        require(len(INPUT['documents'])>=3,'index needs at least three documents')
        return {'documents':INPUT['documents']}
    if STAGE == 'clean':
        docs=previous()['documents']
        return {'documents':[{'id':doc['id'],'text':' '.join(re.sub('<[^>]+>',' ',doc['text']).split())} for doc in docs]}
    if STAGE == 'chunk':
        chunks=[]
        for doc in previous()['documents']:
            sentences=re.split(r'(?<=[.!?])\s+',doc['text'])
            chunks.extend({'document':doc['id'],'text':text} for text in sentences if tokenize(text))
        return {'chunks':chunks}
    if STAGE == 'embed':
        chunks=previous()['chunks'];vocabulary=sorted({term for chunk in chunks for term in tokenize(chunk['text'])})
        idf=[math.log((len(chunks)+1)/(1+sum(term in tokenize(c['text']) for c in chunks)))+1 for term in vocabulary]
        return {'vocabulary':vocabulary,'idf':idf,'chunks':[{**c,'vector':vectorize(c['text'],vocabulary,idf)} for c in chunks],'method':'normalized TF-IDF; no hosted embedding API'}
    if STAGE == 'build-index':
        index=previous();write_json('index.json',index);return index
    if STAGE in ('retrieval-tests','answer-tests'):
        index=previous();results=[]
        for question in INPUT['questions']:
            answer=retrieve(index,question['question'])
            passed=(answer['document']==question['document']) if STAGE=='retrieval-tests' else (question['contains'].lower() in answer['text'].lower())
            results.append({'question':question['question'],'answer':answer,'passed':passed})
        require(all(r['passed'] for r in results),f'{STAGE} failed known-answer checks')
        return {'tests':results,'passed':len(results),'total':len(results)}
    if STAGE == 'publish':
        return write_json('evaluation.json',{'retrieval':read_stage('retrieval-tests'),'answers':read_stage('answer-tests'),'answerMethod':'extractive retrieval from indexed source sentences'})
    raise ValueError(STAGE)


def compute():
    return rag_indexing()

if __name__ == '__main__':
    run_stage()
